\set ON_ERROR_STOP on
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();admin uuid:=gen_random_uuid();pgid uuid:=gen_random_uuid();asset uuid:=gen_random_uuid();post_id uuid;comment_id uuid;room uuid;request uuid;result jsonb;before_count bigint;message_id uuid;report_id uuid;reply_id uuid;comment_asset uuid:=gen_random_uuid();
begin
 insert into public.app_users(id,privy_user_id,verified_email)values(a,'did:privy:group-content-'||a,a||'@example.test'),(b,'did:privy:group-content-'||b,b||'@example.test'),(outsider,'did:privy:group-content-'||outsider,outsider||'@example.test');
 insert into public.admin_allowlist(id,email,active,role)values(admin,a||'@example.test',true,'admin');
 insert into public.group_pages(id,kind,name)values(pgid,'hobby','Hobby');insert into public.group_memberships(page_id,app_user_id,role)values(pgid,a,'owner'),(pgid,b,'member');
 insert into public.mobile_media_assets(id,app_user_id,kind,purpose,content_type,expected_byte_size,actual_byte_size,storage_path,thumbnail_path,state,width,height,request_id,request_hash)values(asset,b,'image','group_post','image/png',100,100,'private/original.png','private/thumbnail.webp','ready',20,20,gen_random_uuid(),'fixture');
 result:=public.groups_content_dispatch('post',b,pgid,null,jsonb_build_object('title','Private','body','Member content','visibility','members','assetIds',jsonb_build_array(asset),'requestId',gen_random_uuid()));post_id:=(result->>'id')::uuid;
 if jsonb_array_length(result->'assets')<>1 then raise exception 'attachment missing';end if;
 if public.authorize_group_media_read(null,asset,'original')is not null or public.authorize_group_media_read(outsider,asset,'original')is not null then raise exception 'private media leaked';end if;
 if public.authorize_group_media_read(a,asset,'original')->>'storagePath'<>'private/original.png' then raise exception 'member media inaccessible';end if;
 perform public.groups_dispatch('leave',b,pgid);
 if public.authorize_group_media_read(b,asset,'original')is not null or public.authorize_mobile_media_read(b,asset,'original')is not null then raise exception 'former author could read private media';end if;
 perform public.groups_dispatch('join',b,pgid,null,jsonb_build_object('requestId',gen_random_uuid()));
 begin perform public.groups_content_dispatch('post',a,pgid,null,jsonb_build_object('title','Stolen','body','Content','visibility','public','assetIds',jsonb_build_array(asset),'requestId',gen_random_uuid()));raise exception 'stolen asset accepted';exception when raise_exception then if sqlerrm<>'GROUPS_INVALID_REQUEST' then raise;end if;end;
 insert into public.mobile_media_assets(id,app_user_id,kind,purpose,content_type,expected_byte_size,actual_byte_size,storage_path,thumbnail_path,state,width,height,request_id,request_hash)values(comment_asset,b,'image','group_post','image/png',100,100,'private/comment.png','private/comment.webp','ready',20,20,gen_random_uuid(),'comment-fixture');
 if public.groups_content_dispatch('notifications',a,pgid)->>'enabled'<>'true'then raise exception 'default page notifications wrong';end if;
 perform public.groups_content_dispatch('set-notifications',a,pgid,null,jsonb_build_object('enabled',false));
 before_count:=(select count(*)from public.fan_web_notification_intents where recipient_app_user_id=a);
 update public.group_pages set anonymous=true where id=pgid;
 result:=public.groups_content_dispatch('comment',b,pgid,post_id,jsonb_build_object('body','Anonymous comment','assetIds',jsonb_build_array(comment_asset),'requestId',gen_random_uuid()));comment_id:=(result->>'id')::uuid;
 if(select count(*)from public.fan_web_notification_intents where recipient_app_user_id=a)<>before_count then raise exception 'muted page sent comment notification';end if;
 if public.authorize_group_media_read(outsider,comment_asset,'original')is not null or public.authorize_group_media_read(a,comment_asset,'original')is null then raise exception 'comment attachment ACL wrong';end if;
 perform public.groups_dispatch('leave',b,pgid);
 if public.authorize_group_media_read(b,comment_asset,'original')is not null then raise exception 'former comment author retained private media';end if;
 perform public.groups_dispatch('join',b,pgid,null,jsonb_build_object('requestId',gen_random_uuid()));
 reply_id:=(public.groups_content_dispatch('comment',a,pgid,post_id,jsonb_build_object('body','Reply','parentId',comment_id,'requestId',gen_random_uuid()))->>'id')::uuid;
 begin perform public.groups_content_dispatch('comment',b,pgid,post_id,jsonb_build_object('body','Nested reply','parentId',reply_id,'requestId',gen_random_uuid()));raise exception 'nested reply allowed';exception when raise_exception then if sqlerrm<>'GROUPS_INVALID_REQUEST'then raise;end if;end;
 update public.group_pages set anonymous=false where id=pgid;
 result:=public.groups_content_dispatch('comments',a,pgid,post_id);
 if result#>>'{items,0,profileId}'is not null or result#>>'{items,0,anonymous}'<>'true' or result#>>'{items,0,canDelete}'<>'true' then raise exception 'anonymous snapshot leaked';end if;
 insert into public.user_blocks(app_user_id,blocked_app_user_id)values(a,b);
 if public.group_post_visible(a,post_id)or public.authorize_group_media_read(a,comment_asset,'original')is not null then raise exception 'blocked author private content exposed';end if;
 delete from public.user_blocks where app_user_id=a and blocked_app_user_id=b;
 begin perform public.groups_content_dispatch('comments',outsider,pgid,post_id);raise exception 'private comments leaked';exception when raise_exception then if sqlerrm<>'GROUPS_NOT_FOUND' then raise;end if;end;
 request:=gen_random_uuid();result:=public.groups_content_dispatch('reaction',b,pgid,post_id,jsonb_build_object('liked',true,'requestId',request));
 perform public.groups_content_dispatch('reaction',b,pgid,post_id,jsonb_build_object('liked',true,'requestId',request));
 if (result->>'count')::integer<>1 then raise exception 'reaction replay duplicated';end if;
 perform public.groups_content_dispatch('comment-remove',b,pgid,comment_id);
 if public.authorize_group_media_read(a,comment_asset,'original')is not null then raise exception 'removed comment attachment leaked';end if;
 if jsonb_array_length(public.groups_content_dispatch('comments',a,pgid,post_id)->'items')<>0 then raise exception 'deleted comment shown';end if;
 begin perform public.groups_content_dispatch('post',b,pgid,null,jsonb_build_object('title','Notice','body','No','visibility','public','category','notice','requestId',gen_random_uuid()));raise exception 'member wrote notice';exception when raise_exception then if sqlerrm<>'GROUPS_FORBIDDEN' then raise;end if;end;
 room:=(public.groups_dispatch('room',a,pgid,null,jsonb_build_object('name','Room','minimumTier','Gold','requestId',gen_random_uuid()))->>'id')::uuid;
 perform public.groups_content_dispatch('room-state',a,pgid,room,jsonb_build_object('name','Room','minimumTier','Gold','status','scheduled','opensAt',now()-interval '1 minute','requestId',gen_random_uuid()));
 result:=public.groups_content_dispatch('rooms',b,pgid);
 if result#>>'{items,0,status}'<>'open' then raise exception 'scheduled room did not open';end if;
 request:=gen_random_uuid();message_id:=(public.groups_content_dispatch('message',a,pgid,room,jsonb_build_object('body','Unread message','requestId',request))->>'id')::uuid;
 insert into public.user_blocks(app_user_id,blocked_app_user_id)values(b,a);
 if jsonb_array_length(public.groups_content_dispatch('messages',b,pgid,room)->'items')<>0 or public.groups_content_dispatch('rooms',b,pgid)#>>'{items,0,latestMessage}'is not null then raise exception 'blocked room message exposed';end if;
 delete from public.user_blocks where app_user_id=b and blocked_app_user_id=a;
 if public.groups_content_dispatch('rooms',b,pgid)#>>'{items,0,unreadCount}'<>'1' then raise exception 'unread count wrong';end if;
 perform public.groups_content_dispatch('room-read',b,pgid,room);
 perform public.groups_content_dispatch('messages',b,pgid,room);
 if public.groups_content_dispatch('rooms',b,pgid)#>>'{items,0,unreadCount}'<>'0' then raise exception 'read cursor not saved';end if;
 update public.group_rooms set status='closed'where id=room;
 result:=public.groups_content_dispatch('rooms',b,pgid);
 if result#>>'{items,0,canEnter}'<>'false' or result#>>'{items,0,latestMessage}'is not null or result#>>'{items,0,unreadCount}'is not null then raise exception 'closed room preview leaked';end if;
 update public.group_rooms set status='scheduled',opens_at=now()+interval '1 day'where id=room;
 result:=public.groups_content_dispatch('rooms',b,pgid);
 if result#>>'{items,0,canEnter}'<>'false' or result#>>'{items,0,latestMessage}'is not null then raise exception 'scheduled room preview leaked';end if;
 update public.group_rooms set status='open',opens_at=null,closes_at=now()-interval '1 minute'where id=room;
 result:=public.groups_content_dispatch('rooms',b,pgid);
 if result#>>'{items,0,canEnter}'<>'false' or result#>>'{items,0,latestMessage}'is not null then raise exception 'expired room preview leaked';end if;
 update public.group_rooms set status='open',closes_at=null where id=room;
 perform public.groups_content_dispatch('heartbeat',b,pgid);
 if public.groups_content_dispatch('presence',null,pgid)->>'onlineCount'<>'1' then raise exception 'presence absent';end if;
 begin perform public.groups_content_dispatch('heartbeat',outsider,pgid);raise exception 'unjoined presence recorded';exception when raise_exception then if sqlerrm<>'GROUPS_FORBIDDEN' then raise;end if;end;
 report_id:=(public.groups_content_dispatch('report',b,pgid,null,jsonb_build_object('targetType','message','targetId',message_id,'reason','Review message','requestId',gen_random_uuid()))->>'id')::uuid;
 begin perform public.groups_content_dispatch('page-reports',b,pgid);raise exception 'ordinary member read reports';exception when raise_exception then if sqlerrm<>'GROUPS_FORBIDDEN'then raise;end if;end;
 result:=public.groups_content_dispatch('page-reports',a,pgid);
 if jsonb_array_length(result->'items')<1 or result#>'{items,0,reporterId}'is not null then raise exception 'operator reports wrong or exposed reporter';end if;
 perform public.groups_content_dispatch('page-resolve-report',a,pgid,report_id,jsonb_build_object('status','action_requested','resolution','Platform review requested','remove',false,'requestId',gen_random_uuid()));
 if(select status from public.group_reports where id=report_id)<>'action_requested'then raise exception 'operator did not escalate report';end if;
 result:=public.groups_content_dispatch('report-evidence',a,pgid,report_id,'{}',admin);
 if result->>'body'<>'Unread message' or result?'authorId' then raise exception 'report evidence wrong';end if;
 begin perform public.groups_content_dispatch('report-evidence',a,pgid,report_id);raise exception 'member read admin evidence';exception when raise_exception then if sqlerrm<>'GROUPS_FORBIDDEN'then raise;end if;end;
 perform public.groups_content_dispatch('resolve-report',a,pgid,report_id,jsonb_build_object('status','resolved','resolution','Removed message','remove',true,'requestId',gen_random_uuid()),admin);
 if jsonb_array_length(public.groups_content_dispatch('messages',b,pgid,room)->'items')<>0 or public.groups_content_dispatch('rooms',b,pgid)#>>'{items,0,latestMessage}'is not null then raise exception 'removed message surfaced';end if;
 if public.groups_content_dispatch('message',a,pgid,room,jsonb_build_object('body','Unread message','requestId',request))->>'body'is not null then raise exception 'message replay exposed removed content';end if;
 if public.groups_content_dispatch('report-evidence',a,pgid,report_id,'{}',admin)->>'body'is not null then raise exception 'removed evidence exposed body';end if;
 result:=public.groups_content_dispatch('report',a,pgid,null,jsonb_build_object('targetType','post','targetId',post_id,'reason','Review this','requestId',gen_random_uuid()));
 report_id:=(result->>'id')::uuid;
 result:=public.groups_content_dispatch('report-evidence',a,pgid,report_id,'{}',admin);
 if jsonb_array_length(result->'attachments')<>1 then raise exception 'admin evidence assets missing';end if;
 if public.authorize_group_report_media_read(a,admin,pgid,report_id,asset,'original',gen_random_uuid())->>'storagePath'<>'private/original.png'then raise exception 'admin private evidence denied';end if;
 if public.authorize_group_report_media_read(a,admin,pgid,report_id,comment_asset,'original',gen_random_uuid())is not null then raise exception 'unrelated report asset read';end if;
 begin perform public.authorize_group_report_media_read(outsider,admin,pgid,report_id,asset,'original',gen_random_uuid());raise exception 'allowlist ID impersonation permitted';exception when raise_exception then if sqlerrm<>'GROUPS_FORBIDDEN'then raise;end if;end;
 perform public.groups_content_dispatch('resolve-report',a,pgid,report_id,jsonb_build_object('status','resolved','resolution','Removed','remove',true,'requestId',gen_random_uuid()),admin);
 if public.authorize_group_report_media_read(a,admin,pgid,report_id,asset,'original',gen_random_uuid())is not null then raise exception 'removed admin media remained accessible';end if;
 if public.authorize_group_media_read(b,asset,'original')is not null then raise exception 'moderated attachment leaked';end if;
end $$;
rollback;
